#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Run from the repo root so .env and docker-compose.yml resolve consistently.
cd "$(dirname "$0")/.."

TOTAL_STAGES=8

banner "排课系统二期 · 本机 Docker + 真实 AI 冒烟"

rand32() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex 32
  else
    head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n'
  fi
}

# json_get dot.path reads a value from JSON on stdin. Node ships with the frontend.
json_get() {
  node -e '
    let data = "";
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => {
      let value;
      try { value = JSON.parse(data); } catch { return; }
      for (const key of process.argv[1].split(".")) value = value == null ? value : value[key];
      process.stdout.write(value == null ? "" : String(value));
    });
  ' "$1"
}

TOKEN=""
api() {
  local method="$1" path="$2" body="${3:-}"
  if [[ -n "$body" ]]; then
    curl -s -X "$method" "http://localhost:8080/api$path" \
      -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" -d "$body" || true
  else
    curl -s -X "$method" "http://localhost:8080/api$path" -H "Authorization: Bearer $TOKEN" || true
  fi
}

provider_id_by_name() {
  api GET /ai-providers | node -e '
    let data = "";
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => {
      let list = [];
      try { list = JSON.parse(data); } catch { return; }
      const provider = list.find((item) => item.name === process.argv[1]);
      process.stdout.write(provider ? String(provider.id) : "");
    });
  ' "$1"
}

provider_model_id_by_name() {
  api GET /ai-providers | node -e '
    let data = "";
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => {
      let list = [];
      try { list = JSON.parse(data); } catch { return; }
      const provider = list.find((item) => item.name === process.argv[1]);
      const model = provider && provider.models && provider.models[0];
      process.stdout.write(model ? String(model.id) : "");
    });
  ' "$1"
}

# ── Stage 1: Docker ───────────────────────────────────────────────────────
stage "前置检查：Docker"
say "本机用 docker compose 启动 Postgres、后端和前端。"
if ! command -v docker >/dev/null 2>&1; then
  warn "未找到 docker。"
  open_url "https://www.docker.com/products/docker-desktop/"
  step "安装 Docker Desktop 并启动它（Windows 建议启用 WSL2 后端）。"
  pause "安装完成、docker compose version 可用后按 Enter"
fi
command -v docker >/dev/null 2>&1 || { warn "仍然找不到 docker，退出。"; exit 1; }
docker info >/dev/null 2>&1 || {
  warn "Docker 已安装但没有运行。"
  step "启动 Docker Desktop，等状态变为 Running。"
  pause "Docker 运行后按 Enter"
  docker info >/dev/null 2>&1 || { warn "Docker 仍不可用，退出。"; exit 1; }
}
docker compose version >/dev/null 2>&1 || { warn "docker compose 插件不可用，请升级 Docker Desktop。"; exit 1; }
note "Docker 就绪。"

# ── Stage 2: local secrets ────────────────────────────────────────────────
stage "生成本地密钥并写入 .env"
say "生成 JWT 签名密钥与 AI API Key 加密密钥，只写进 .env（已被 .gitignore 忽略）。"
JWT_SECRET=$(_existing PAIBAN_JWT_SECRET || true)
[[ -n "$JWT_SECRET" ]] || JWT_SECRET=$(rand32)
AI_ENCRYPTION_KEY=$(_existing PAIBAN_AI_ENCRYPTION_KEY || true)
[[ -n "$AI_ENCRYPTION_KEY" ]] || AI_ENCRYPTION_KEY=$(rand32)
write_env PAIBAN_JWT_SECRET "$JWT_SECRET"
write_env PAIBAN_AI_ENCRYPTION_KEY "$AI_ENCRYPTION_KEY"
note "已有 .env 时保留原值；想轮换就删掉对应行再跑。"

# ── Stage 3: DeepSeek ─────────────────────────────────────────────────────
stage "DeepSeek API Key"
say "DeepSeek 用于调代推荐（文本）。"
open_url "https://platform.deepseek.com/api_keys"
step "登录后进入 API keys，点 Create new API key。"
step "复制以 sk- 开头的 key（只显示一次）。"
ask_secret DEEPSEEK_API_KEY "粘贴 DeepSeek API Key："
[[ -n "$DEEPSEEK_API_KEY" ]] || { warn "空值，退出。"; exit 1; }
write_env DEEPSEEK_API_KEY "$DEEPSEEK_API_KEY"

# ── Stage 4: Gemini ───────────────────────────────────────────────────────
stage "Gemini API Key"
say "Gemini 用于 AI 数据导入（含图片/视觉）。"
open_url "https://aistudio.google.com/app/apikey"
step "点 Create API key，选择或新建项目。"
step "复制生成的 key。"
ask_secret GEMINI_API_KEY "粘贴 Gemini API Key："
[[ -n "$GEMINI_API_KEY" ]] || { warn "空值，退出。"; exit 1; }
write_env GEMINI_API_KEY "$GEMINI_API_KEY"

# ── Stage 5: compose stack ────────────────────────────────────────────────
stage "启动 Docker Compose 栈"
say "会构建镜像并启动 Postgres + 后端 + 前端。首次构建可能需要几分钟。"
confirm "现在执行 docker compose up -d --build？" || { warn "已取消。"; exit 0; }
docker compose up -d --build
say "等待后端健康检查..."
for _ in $(seq 1 60); do
  if curl -s -o /dev/null -w "%{http_code}" http://localhost:8080/api/health | grep -q 200; then
    note "后端已就绪。"
    break
  fi
  sleep 2
done
if ! curl -s -o /dev/null -w "%{http_code}" http://localhost:8080/api/health | grep -q 200; then
  warn "后端未在 2 分钟内就绪，下面是最近日志："
  docker compose logs --tail=80 backend || true
  exit 1
fi
open_url "http://localhost:5173"

# ── Stage 6: providers and task routing ───────────────────────────────────
stage "登录并创建两个 AI 供应商"
ADMIN_PASSWORD=""
ask_secret ADMIN_PASSWORD "管理员密码（默认 admin123，直接 Enter）："
[[ -n "$ADMIN_PASSWORD" ]] || ADMIN_PASSWORD="admin123"
TOKEN=$(curl -s -X POST http://localhost:8080/api/auth/login \
  -H "Content-Type: application/json" \
  -d "{\"username\":\"admin\",\"password\":\"$ADMIN_PASSWORD\"}" | json_get token)
[[ -n "$TOKEN" ]] || { warn "登录失败，请确认管理员密码。"; exit 1; }

say "创建或复用 DeepSeek 供应商（deepseek-chat）。"
DS_ID=$(provider_id_by_name "DeepSeek")
if [[ -z "$DS_ID" ]]; then
  DS_JSON=$(api POST /ai-providers "{\"name\":\"DeepSeek\",\"type\":\"preset\",\"baseUrl\":\"https://api.deepseek.com\",\"apiKey\":\"$DEEPSEEK_API_KEY\",\"enabled\":true,\"models\":[{\"modelName\":\"deepseek-chat\",\"displayName\":\"DeepSeek Chat\",\"visionCapable\":false,\"enabled\":true}]}")
  DS_ID=$(printf '%s' "$DS_JSON" | json_get id)
  [[ -n "$DS_ID" ]] || { warn "创建 DeepSeek 失败：$DS_JSON"; exit 1; }
  note "已创建 DeepSeek（id=$DS_ID）。"
else
  note "复用已有 DeepSeek（id=$DS_ID）。"
fi
DS_MODEL_ID=$(provider_model_id_by_name "DeepSeek")
[[ -n "$DS_MODEL_ID" ]] || { warn "DeepSeek 下没有模型，请先在设置中心添加 deepseek-chat。"; exit 1; }

say "创建或复用 Gemini 供应商（gemini-2.0-flash，支持视觉）。"
G_ID=$(provider_id_by_name "Gemini")
if [[ -z "$G_ID" ]]; then
  G_JSON=$(api POST /ai-providers "{\"name\":\"Gemini\",\"type\":\"preset\",\"baseUrl\":\"https://generativelanguage.googleapis.com/v1beta\",\"apiKey\":\"$GEMINI_API_KEY\",\"enabled\":true,\"models\":[{\"modelName\":\"gemini-2.0-flash\",\"displayName\":\"Gemini 2.0 Flash\",\"visionCapable\":true,\"enabled\":true}]}")
  G_ID=$(printf '%s' "$G_JSON" | json_get id)
  [[ -n "$G_ID" ]] || { warn "创建 Gemini 失败：$G_JSON"; exit 1; }
  note "已创建 Gemini（id=$G_ID）。"
else
  note "复用已有 Gemini（id=$G_ID）。"
fi
G_MODEL_ID=$(provider_model_id_by_name "Gemini")
[[ -n "$G_MODEL_ID" ]] || { warn "Gemini 下没有模型，请先在设置中心添加 gemini-2.0-flash。"; exit 1; }

say "测试连通性..."
DS_TEST=$(api POST "/ai-providers/$DS_ID/test")
G_TEST=$(api POST "/ai-providers/$G_ID/test")
note "DeepSeek: $(printf '%s' "$DS_TEST" | json_get message)"
note "Gemini:   $(printf '%s' "$G_TEST" | json_get message)"
[[ "$(printf '%s' "$DS_TEST" | json_get success)" == "true" ]] || warn "DeepSeek 连接测试未通过。"
[[ "$(printf '%s' "$G_TEST" | json_get success)" == "true" ]] || warn "Gemini 连接测试未通过。"

say "任务分配：数据导入 → Gemini（视觉），调代推荐 → DeepSeek。"
api PUT /ai-task-config "{\"mode\":\"custom\",\"tasks\":[{\"taskType\":\"data_import\",\"providerId\":$G_ID,\"modelId\":$G_MODEL_ID},{\"taskType\":\"substitution_recommend\",\"providerId\":$DS_ID,\"modelId\":$DS_MODEL_ID}]}" >/dev/null

# ── Stage 7: real AI smoke ────────────────────────────────────────────────
stage "真实 AI 冒烟"
say "用一段文本走完整的 AI 导入解析（只生成预览，不入库）。"
IMPORT_JSON=$(api POST /ai/import/text '{"text":"张老师教语文，电话13800000001；李老师教数学"}')
SESSION_ID=$(printf '%s' "$IMPORT_JSON" | json_get sessionId)
if [[ -n "$SESSION_ID" ]]; then
  ROW_COUNT=$(printf '%s' "$IMPORT_JSON" | json_get rows.length)
  note "AI 解析成功：session=$SESSION_ID，rows=$ROW_COUNT"
  open_url "http://localhost:5173/admin/ai-import"
else
  warn "AI 解析未返回 sessionId：$IMPORT_JSON"
fi
say "AI 状态："
api GET /ai/status
printf '\n'
pause "确认预览正常后按 Enter"

# ── Stage 8: close-out ────────────────────────────────────────────────────
stage "收尾检查"
say ".env 含有密钥，已被 .gitignore 忽略；不要提交或发给别人。"
step "在设置中心修改默认管理员密码（admin/admin123 只用于首次启动）。"
step "把 .env 备份到安全位置；丢失 PAIBAN_AI_ENCRYPTION_KEY 后已保存的 API Key 将无法解密。"
docker compose ps || true
open_url "http://localhost:5173/admin/ai-providers"
note "停止：docker compose down；数据在 paiban-pgdata 卷与 ./data/uploads。"

finish
